response:
**Gates before launch**

First, I confirm the git tree is clean. I also confirm that the commit holding spe/predictions/r04.yaml and spe/plans/r04.md is older than the run, so the predictions were locked before any results existed. Next, I run grade.py against two fixture files. One fixture is all correct and should score 100%. The other has known errors and should score the exact lower number I expect. Then I check that answers.json has exactly 50 entries and that its ticket ids match the 50 tickets I pass in args. I check that both config prompts are 12 lines long. I also check that B has 6 tools and C2 has 3 tools plus check_status. After that, I run one ticket through each config and through the judge as a smoke test. The smoke test gives me a measured per-call cost. I use that cost to confirm that 500 trials plus 500 judge calls, plus the smoke spend, fit under $40. The script repeats the shape and budget checks itself and stops at Preflight if any of them fail. After the run, the main session saves the returned rows under spe/evals/ and runs grade.py on them. Then it makes a local commit. It does not push.

**Script**

```js
export const meta = {
  name: 'spe-r04-eval',
  description: 'SPE round 4. Config B vs C2 on 50 tickets, 5 trials per cell, Opus tone judge, $40 cap. Category and priority are graded after the run by spe/evals/graders/grade.py.',
  phases: [
    { title: 'Preflight' },
    { title: 'Trials' },
    { title: 'Summary' },
  ],
}

// The main session builds args from repo files before launch. The script cannot read files.
// args = {
//   tickets: [{ id, subject, body }],          // 50 tickets from spe/evals/tasks/
//   configs: {
//     B:  { prompt, tools: [{ name, description }], model },   // 12 lines, 6 tools
//     C2: { prompt, tools: [{ name, description }], model },   // 12 lines, 3 tools + check_status
//   },
//   judgeRubric: '<contents of spe/evals/graders/judge.md>',
//   trials: 5,
//   capUsd: 40,
//   estUsdPerTrial: <number from smoke test>,
//   estUsdPerJudge: <number from smoke test>,
//   spentUsd: <smoke test spend already incurred>,
// }

const A = args || {}
const CONFIG_NAMES = ['B', 'C2']

const TRIAL_SCHEMA = {
  type: 'object',
  properties: {
    label: {
      type: 'object',
      properties: {
        category: { type: 'string' },
        priority: { type: 'string' },
      },
      required: ['category', 'priority'],
    },
    reply: { type: 'string' },
    tool_calls: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          name: { type: 'string' },
          input: { type: 'object' },
        },
        required: ['name'],
      },
    },
  },
  required: ['label', 'reply', 'tool_calls'],
}

const JUDGE_SCHEMA = {
  type: 'object',
  properties: {
    score: { type: 'integer', minimum: 1, maximum: 5 },
    pass: { type: 'boolean' },
    reason: { type: 'string' },
  },
  required: ['score', 'pass', 'reason'],
}

function trialPrompt(cfg, ticket) {
  const toolList = cfg.tools.map(t => `- ${t.name}: ${t.description}`).join('\n')
  return `${cfg.prompt}

## Tools available in this configuration
${toolList}

## Ticket ${ticket.id}
Subject: ${ticket.subject}

${ticket.body}

## What to return
This is an offline eval. Do not use any real tools. Do not read or write files.
Return the label you would apply (category and priority), the reply you would send
to the customer, and the tool calls you would make, in order, with their inputs.`
}

function judgePrompt(ticket, reply) {
  return `${A.judgeRubric}

## Customer ticket
Subject: ${ticket.subject}

${ticket.body}

## Reply to grade
${reply}

Grade only the tone of the reply, using the rubric above.
Do not use any tools. Return score, pass, and reason.`
}

async function runTrial(item) {
  const cfg = A.configs[item.config]
  try {
    const out = await agent(trialPrompt(cfg, item.ticket), {
      label: `r04 ${item.config} t${item.trial} ${item.ticket.id}`,
      phase: 'Trials',
      schema: TRIAL_SCHEMA,
      model: cfg.model || 'opus',
    })
    if (!out) return { ...item, out: null, error: 'trial agent returned no output' }
    return { ...item, out, error: null }
  } catch (e) {
    return { ...item, out: null, error: `trial: ${String(e?.message || e)}` }
  }
}

async function runJudge(item) {
  const base = {
    ticketId: item.ticket.id,
    config: item.config,
    trial: item.trial,
    label: item.out?.label ?? null,
    reply: item.out?.reply ?? null,
    toolCalls: item.out?.tool_calls ?? null,
    judge: null,
    error: item.error,
  }
  if (item.error || !base.reply) return base
  try {
    // The judge never sees the config name or the label. It is blind to the arm.
    const j = await agent(judgePrompt(item.ticket, base.reply), {
      label: `r04 judge t${item.trial} ${item.ticket.id} ${item.config === 'B' ? 'x' : 'y'}`,
      phase: 'Trials',
      schema: JUDGE_SCHEMA,
      model: 'opus',
    })
    return { ...base, judge: j || null, error: j ? null : 'judge returned no output' }
  } catch (e) {
    return { ...base, error: `judge: ${String(e?.message || e)}` }
  }
}

// ---------- Preflight ----------
phase('Preflight')

const problems = []
const tickets = Array.isArray(A.tickets) ? A.tickets : []
if (tickets.length !== 50) problems.push(`expected 50 tickets, got ${tickets.length}`)
if (new Set(tickets.map(t => t.id)).size !== tickets.length) problems.push('ticket ids are not unique')

for (const name of CONFIG_NAMES) {
  const c = A.configs?.[name]
  if (!c) { problems.push(`missing config ${name}`); continue }
  const lines = String(c.prompt || '').trim().split('\n').length
  if (lines !== 12) problems.push(`config ${name} prompt has ${lines} lines, plan says 12`)
  if (!Array.isArray(c.tools)) problems.push(`config ${name} has no tools array`)
}
if ((A.configs?.B?.tools || []).length !== 6) problems.push('config B must have 6 tools')
const c2Tools = A.configs?.C2?.tools || []
if (c2Tools.length !== 4 || !c2Tools.some(t => t.name === 'check_status')) {
  problems.push('config C2 must have 3 tools plus check_status')
}
if (A.trials !== 5) problems.push(`plan says 5 trials, args say ${A.trials}`)
if (!A.judgeRubric) problems.push('judgeRubric is empty')
for (const k of ['capUsd', 'estUsdPerTrial', 'estUsdPerJudge']) {
  if (typeof A[k] !== 'number' || !(A[k] > 0)) problems.push(`${k} must be a positive number`)
}
if (A.capUsd > 40) problems.push(`plan caps spend at $40, args say $${A.capUsd}`)

if (problems.length) {
  log(`Preflight failed:\n- ${problems.join('\n- ')}`)
  throw new Error(`Preflight failed: ${problems.join('; ')}`)
}

const startSpent = A.spentUsd || 0
const perRound = tickets.length * CONFIG_NAMES.length * (A.estUsdPerTrial + A.estUsdPerJudge)
const projected = startSpent + perRound * A.trials
log(`Plan: ${CONFIG_NAMES.length} configs x ${tickets.length} tickets x ${A.trials} trials = ${CONFIG_NAMES.length * tickets.length * A.trials} trials plus the same number of judge calls.`)
log(`Projected spend $${projected.toFixed(2)} of $${A.capUsd} cap (estimate from smoke test, not metered).`)
if (projected > A.capUsd) {
  throw new Error(`Projected spend $${projected.toFixed(2)} is over the $${A.capUsd} cap. Not launching.`)
}

// ---------- Trials ----------
// Each round runs one trial index for both configs over all tickets.
// If the cap stops the run early, both arms have the same number of trials.
phase('Trials')

const results = []
let spent = startSpent
let stoppedEarly = false

for (let t = 1; t <= A.trials; t++) {
  if (spent + perRound > A.capUsd) {
    stoppedEarly = true
    log(`Stopping before round ${t}. Estimated spend $${spent.toFixed(2)} plus $${perRound.toFixed(2)} would pass the $${A.capUsd} cap.`)
    break
  }
  const items = []
  for (const ticket of tickets) {
    for (const config of CONFIG_NAMES) items.push({ ticket, config, trial: t })
  }
  const rows = await pipeline(items, runTrial, runJudge)
  results.push(...rows)
  spent += perRound
  const errs = rows.filter(r => r.error).length
  log(`Round ${t}/${A.trials} done. ${rows.length} rows, ${errs} errors. Estimated spend $${spent.toFixed(2)}.`)
}

// ---------- Summary ----------
// Category and priority accuracy is not computed here. grade.py does that after the run.
phase('Summary')

const summary = {}
for (const name of CONFIG_NAMES) {
  const rows = results.filter(r => r.config === name)
  const judged = rows.filter(r => r.judge)
  const meanScore = judged.length
    ? judged.reduce((s, r) => s + r.judge.score, 0) / judged.length
    : null
  summary[name] = {
    rows: rows.length,
    errors: rows.filter(r => r.error).length,
    judged: judged.length,
    toneMean: meanScore,
    tonePassRate: judged.length ? judged.filter(r => r.judge.pass).length / judged.length : null,
    checkStatusCalls: rows.filter(r => (r.toolCalls || []).some(c => c.name === 'check_status')).length,
  }
}
log(`Summary: ${JSON.stringify(summary)}`)

return {
  round: 'r04',
  stoppedEarly,
  estimatedSpendUsd: Number(spent.toFixed(2)),
  capUsd: A.capUsd,
  summary,
  results,
}
```

**Gaps you should know about**

1. agent() has no option for setting a tool list. In this script, each config's tools are listed in the prompt. The trial agent declares its tool calls but does not run them. I did not read r03-workflow.js because this trial allows no tools. If round 3 ran the system under test through a harness command instead, runTrial should use that pattern so rounds 3 and 4 stay comparable.
2. The script cannot meter real spend. The $40 cap uses per-call estimates from the smoke test. Calls that cost more than the smoke test could push actual spend past $40.
3. grade.py is not called inside the script because the script has no filesystem access. The script returns label.category and label.priority for every row. The main session grades them against answers.json after the run.
